import { hexDistance, hexLine, type AxialCoord, type HexCell } from "./hex.ts";

export type SignalType = "ambient" | "origin" | "path" | "broadcast";
export type SignalState = "idle" | "origin" | "propagating" | "receiving" | "resolved";

export interface SignalTarget extends AxialCoord {
  id?: string;
}

export interface TopologySignal {
  id: string;
  type: SignalType;
  origin: AxialCoord;
  targets?: SignalTarget[];
  path?: AxialCoord[];
  startedAt: number;
  duration: number;
  intensity: number;
  state?: SignalState;
  radius?: number;
}

export interface SignalCellState {
  id: string;
  q?: number;
  r?: number;
  state: SignalState;
  intensity: number;
  type?: SignalType;
}

export interface SignalWaveOptions {
  cells: HexCell[];
  origin: AxialCoord;
  maxRadius: number;
  frame: number;
  width?: number;
}

export interface SignalFrameOptions {
  cells: HexCell[];
  signals: TopologySignal[];
  now?: number;
}

function clamp(value: number, min = 0, max = 1) {
  return Math.min(max, Math.max(min, value));
}

function hashString(input: string) {
  let hash = 2166136261;

  for (let i = 0; i < input.length; i += 1) {
    hash ^= input.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }

  return hash >>> 0;
}

function seededValue(seed: string | number | undefined, value: string) {
  return hashString(`${seed ?? "topology"}:${value}`) / 4294967295;
}

function signalKey(signal: Pick<TopologySignal, "type" | "origin" | "startedAt">) {
  return `${signal.type}:${signal.origin.q},${signal.origin.r}:${signal.startedAt}`;
}

export function createSignalId(type: SignalType, origin: AxialCoord, startedAt = 0) {
  return `${type}:${origin.q},${origin.r}:${startedAt}`;
}

export function createAmbientSignal(origin: AxialCoord, options: Partial<Pick<TopologySignal, "duration" | "intensity" | "startedAt" | "radius">> = {}): TopologySignal {
  const startedAt = options.startedAt ?? 0;
  return {
    id: createSignalId("ambient", origin, startedAt),
    type: "ambient",
    origin,
    startedAt,
    duration: options.duration ?? 3200,
    intensity: options.intensity ?? 0.18,
    radius: options.radius ?? 5,
    state: "propagating",
  };
}

export function createOriginSignal(
  origin: AxialCoord,
  targets: SignalTarget[] = [],
  options: Partial<Pick<TopologySignal, "duration" | "intensity" | "startedAt">> = {},
): TopologySignal {
  const startedAt = options.startedAt ?? 0;
  return {
    id: createSignalId("origin", origin, startedAt),
    type: "origin",
    origin,
    targets,
    startedAt,
    duration: options.duration ?? 1800,
    intensity: options.intensity ?? 1,
    state: "origin",
  };
}

export function createPathSignal(
  path: AxialCoord[],
  options: Partial<Pick<TopologySignal, "duration" | "intensity" | "startedAt" | "targets">> = {},
): TopologySignal | null {
  const origin = path[0];
  if (!origin) return null;

  const startedAt = options.startedAt ?? 0;
  return {
    id: createSignalId("path", origin, startedAt),
    type: "path",
    origin,
    targets: options.targets,
    path,
    startedAt,
    duration: options.duration ?? 2200,
    intensity: options.intensity ?? 0.9,
    state: "propagating",
  };
}

export function createReceivingSignal(
  destination: AxialCoord,
  options: Partial<Pick<TopologySignal, "duration" | "intensity" | "startedAt">> = {},
): TopologySignal {
  const startedAt = options.startedAt ?? 0;

  return {
    id: createSignalId("path", destination, startedAt),
    type: "path",
    origin: destination,
    path: [destination],
    startedAt,
    duration: options.duration ?? 320,
    intensity: options.intensity ?? 0.95,
    state: "receiving",
  };
}

export function createBroadcastSignal(
  origin: AxialCoord,
  options: Partial<Pick<TopologySignal, "duration" | "intensity" | "startedAt" | "radius">> = {},
): TopologySignal {
  const startedAt = options.startedAt ?? 0;
  return {
    id: createSignalId("broadcast", origin, startedAt),
    type: "broadcast",
    origin,
    startedAt,
    duration: options.duration ?? 2600,
    intensity: options.intensity ?? 0.82,
    radius: options.radius ?? 7,
    state: "propagating",
  };
}

export function getSignalProgress(signal: TopologySignal, now = signal.startedAt + signal.duration) {
  const elapsed = Math.max(0, now - signal.startedAt);
  return clamp(elapsed / Math.max(1, signal.duration));
}

export function resolveSignalState(signal: TopologySignal, now = signal.startedAt + signal.duration): SignalState {
  if (signal.state && getSignalProgress(signal, now) >= 1) {
    return signal.state;
  }

  const progress = getSignalProgress(signal, now);

  if (progress <= 0.08) return "origin";
  if (progress < 0.7) return "propagating";
  if (progress < 1) return "receiving";
  return signal.state ?? "resolved";
}

export function getGridActivityWave(options: SignalWaveOptions) {
  const { cells, origin, maxRadius, frame, width = 1 } = options;

  const active: SignalCellState[] = [];

  for (let q = origin.q - maxRadius; q <= origin.q + maxRadius; q++) {
    for (let r = origin.r - maxRadius; r <= origin.r + maxRadius; r++) {
      const coord = { q, r };
      const distance = hexDistance(origin, coord);

      if (distance > maxRadius) continue;

      const delta = Math.abs(distance - frame);

      if (delta <= width) {
        active.push({
          q,
          r,
          id: `hex-${coord.q}-${coord.r}`,
          state: delta < 0.5 ? "origin" : delta < 1 ? "propagating" : "receiving",
          intensity: 1 - delta / (width + 1),
        });
      }
    }
  }

  return active;
}

export function getBroadcastWave(options: SignalWaveOptions) {
  const { cells, origin, maxRadius, frame, width = 1 } = options;
  const active: SignalCellState[] = [];
  const activeRadius = Math.max(0, frame);

  for (const cell of cells) {
    const distance = hexDistance(origin, cell);
    if (distance > maxRadius) continue;

    const delta = Math.abs(distance - activeRadius);

    if (delta <= width) {
      active.push({
        q: cell.q,
        r: cell.r,
        id: cell.id,
        state: activeRadius < 1 ? "origin" : "propagating",
        intensity: clamp(1 - delta / (width + 1), 0.08, 1),
      });
      continue;
    }

    if (distance < activeRadius - width) {
      active.push({
        q: cell.q,
        r: cell.r,
        id: cell.id,
        state: "resolved",
        intensity: 0.12,
      });
    }
  }

  return active;
}

export function getGridActivityCellIds(options: SignalWaveOptions) {
  return getGridActivityWave(options).map((cell) => cell.id);
}

export function getBroadcastCellIds(options: SignalWaveOptions) {
  return getBroadcastWave(options).map((cell) => cell.id);
}

export function getGridActivityPathIds(path: AxialCoord[]) {
  return path.map((coord) => `hex-${coord.q}-${coord.r}`);
}

export function getSignalPathIds(path: AxialCoord[]) {
  return getGridActivityPathIds(path);
}

export function getSignalWave(options: SignalWaveOptions) {
  return getGridActivityWave(options);
}

export function getSignalCellIds(options: SignalWaveOptions) {
  return getGridActivityCellIds(options);
}

function createDefaultState(id: string): SignalCellState {
  return {
    id,
    state: "idle",
    intensity: 0.08,
  };
}

function chooseState(current: SignalCellState, next: SignalCellState) {
  const order: Record<SignalState, number> = {
    idle: 0,
    resolved: 1,
    propagating: 2,
    receiving: 3,
    origin: 4,
  };

  if (order[next.state] > order[current.state]) {
    return next;
  }

  if (order[next.state] === order[current.state] && next.intensity > current.intensity) {
    return next;
  }

  return current;
}

function applyRadialSignal(
  cells: HexCell[],
  origin: AxialCoord,
  progress: number,
  maxRadius: number,
  intensity: number,
  activeState: SignalState,
  type: SignalType,
  trailWidth = 1,
) {
  const frame = progress * maxRadius;
  const states = new Map<string, SignalCellState>();

  for (const cell of cells) {
    const distance = hexDistance(origin, cell);
    if (distance > maxRadius) continue;

    const delta = distance - frame;
    const resolved = distance < frame - trailWidth;

    if (resolved) {
      states.set(cell.id, {
        id: cell.id,
        state: "resolved",
        intensity: 0.12 + Math.max(0, 1 - distance / Math.max(1, maxRadius)) * 0.1,
        type,
      });
      continue;
    }

    if (Math.abs(delta) <= trailWidth) {
      states.set(cell.id, {
        id: cell.id,
        state: activeState,
        intensity: clamp(intensity * (1 - Math.abs(delta) / (trailWidth + 1)), 0.08, 1),
        type,
      });
    }
  }

  return states;
}

function applyPathSignal(path: AxialCoord[], progress: number, intensity: number, type: SignalType = "path") {
  const states = new Map<string, SignalCellState>();
  const lastIndex = Math.max(0, path.length - 1);
  const activeIndex = Math.min(lastIndex, Math.max(0, Math.floor(progress * lastIndex)));
  const leadProgress = lastIndex === 0 ? 1 : progress * lastIndex - activeIndex;

  path.forEach((coord, index) => {
    const id = `hex-${coord.q}-${coord.r}`;

    if (progress >= 1) {
      states.set(id, {
        id,
        state: "resolved",
        intensity: 0.16,
        type,
      });
      return;
    }

    if (index === 0) {
      states.set(id, {
        id,
        state: "origin",
        intensity: clamp(intensity * 0.95, 0.08, 1),
        type,
      });
      return;
    }

    if (index < activeIndex) {
      states.set(id, {
        id,
        state: "propagating",
        intensity: clamp(intensity * (1 - index / Math.max(1, path.length) * 0.35), 0.08, 1),
        type,
      });
      return;
    }

    if (index === activeIndex) {
      states.set(id, {
        id,
        state: leadProgress > 0.6 ? "receiving" : "propagating",
        intensity: clamp(intensity * (0.78 + leadProgress * 0.22), 0.08, 1),
        type,
      });
    }
  });

  return states;
}

function applyPathFanOutSignal(
  source: AxialCoord,
  targets: SignalTarget[],
  progress: number,
  intensity: number,
) {
  const states = new Map<string, SignalCellState>();
  const fanOutWindow = 0.28;
  const fanOutStart = 1 - fanOutWindow;

  targets.forEach((target, index) => {
    const targetPath = hexLine(source, target);
    if (targetPath.length < 2) return;

    const stagger = index * 0.08;
    const branchProgress = clamp((progress - fanOutStart - stagger) / Math.max(0.08, fanOutWindow), 0, 1);

    if (branchProgress <= 0) return;

    const branchStates = applyPathSignal(targetPath, branchProgress, intensity * 0.72, "path");
    for (const [id, next] of branchStates) {
      const current = states.get(id) ?? createDefaultState(id);
      states.set(id, chooseState(current, next));
    }
  });

  return states;
}

export function buildSignalFrame(options: SignalFrameOptions): Record<string, SignalCellState> {
  const { cells, signals, now = Date.now() } = options;
  const states = new Map<string, SignalCellState>(cells.map((cell) => [cell.id, createDefaultState(cell.id)]));

  for (const signal of signals) {
    const progress = getSignalProgress(signal, now);

    if (signal.state === "receiving" && (signal.path?.length ?? 0) <= 1) {
      const id = "hex-" + signal.origin.q + "-" + signal.origin.r;
      const receivingState: SignalCellState = {
        id,
        state: "receiving",
        intensity: clamp(signal.intensity * (0.88 + progress * 0.12), 0.08, 1),
        type: signal.type,
      };
      const current = states.get(id) ?? createDefaultState(id);
      states.set(id, chooseState(current, receivingState));
      continue;
    }

    if (signal.type === "ambient") {
      const radius = signal.radius ?? 5;
      const wave = applyRadialSignal(cells, signal.origin, progress, radius, signal.intensity, "propagating", signal.type, Math.max(1, Math.round(radius * 0.18)));

      for (const [id, next] of wave) {
        const current = states.get(id) ?? createDefaultState(id);
        states.set(id, chooseState(current, next));
      }

      continue;
    }

    if (signal.type === "broadcast") {
      const radius = signal.radius ?? 7;
      const wave = applyRadialSignal(cells, signal.origin, progress, radius, signal.intensity, "propagating", signal.type, Math.max(1, Math.round(radius * 0.16)));

      for (const [id, next] of wave) {
        const current = states.get(id) ?? createDefaultState(id);
        states.set(id, chooseState(current, next));
      }

      continue;
    }

    if (signal.type === "origin") {
      const radius = signal.radius ?? 4;
      const wave = applyRadialSignal(cells, signal.origin, progress, radius, signal.intensity, "origin", signal.type, Math.max(1, Math.round(radius * 0.2)));

      for (const [id, next] of wave) {
        const current = states.get(id) ?? createDefaultState(id);
        states.set(id, chooseState(current, next));
      }

      for (const target of signal.targets ?? []) {
        const id = `hex-${target.q}-${target.r}`;
        const targetState: SignalCellState = {
          id,
          state: progress >= 1 ? "resolved" : "receiving",
          intensity: clamp(signal.intensity * (0.75 + progress * 0.25), 0.08, 1),
          type: signal.type,
        };
        const current = states.get(id) ?? createDefaultState(id);
        states.set(id, chooseState(current, targetState));
      }

      continue;
    }

    const path = signal.path ?? (signal.targets?.[0] ? hexLine(signal.origin, signal.targets[0]) : []);
    if (!path.length) continue;

    const pathStates = applyPathSignal(path, progress, signal.intensity, signal.type);
    for (const [id, next] of pathStates) {
      const current = states.get(id) ?? createDefaultState(id);
      states.set(id, chooseState(current, next));
    }

    if ((signal.targets ?? []).length > 0 && path.length > 1) {
      const fanOutStates = applyPathFanOutSignal(path[path.length - 1], signal.targets ?? [], progress, signal.intensity);
      for (const [id, next] of fanOutStates) {
        const current = states.get(id) ?? createDefaultState(id);
        states.set(id, chooseState(current, next));
      }
    }
  }

  return Object.fromEntries(states.entries());
}

export function buildSignalCellStates(options: SignalFrameOptions) {
  return buildSignalFrame(options);
}

export function createSignalFrameKey(signals: TopologySignal[]) {
  return signals.map((signal) => signalKey(signal)).join("|");
}
